schema_run.stdout:
{
  "$defs": {
    "LLMCallConfig": {
      "description": "Per-role LLM call configuration.\n\nOne instance per pipeline role (attacker, evaluator). Controls model\nselection, API type, temperature, token limits, timeout, extra kwargs, and\noptionally an explicit pre-configured client.",
      "properties": {
        "model": {
          "default": "openai/gpt-6-luna",
          "title": "Model",
          "type": "string"
        },
        "api": {
          "default": "chat_completions",
          "enum": [
            "chat_completions",
            "responses"
          ],
          "title": "Api",
          "type": "string"
        },
        "temperature": {
          "anyOf": [
            {
              "maximum": 2.0,
              "minimum": 0.0,
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Sampling temperature. Unset by default: when None the parameter is omitted from the request entirely, so the provider default applies and reasoning-class models that reject ``temperature`` (gpt-5 and the o-series answer 400) keep working. Set it only when you actually want to pin sampling.",
          "title": "Temperature"
        },
        "max_tokens": {
          "default": 10000,
          "exclusiveMinimum": 0,
          "title": "Max Tokens",
          "type": "integer"
        },
        "timeout_ms": {
          "default": 90000,
          "exclusiveMinimum": 0,
          "title": "Timeout Ms",
          "type": "integer"
        },
        "extra_kwargs": {
          "additionalProperties": true,
          "title": "Extra Kwargs",
          "type": "object"
        },
        "extra_body": {
          "additionalProperties": true,
          "description": "Extra fields for the request BODY, for router/provider options the SDK has no named parameter for. Distinct from ``extra_kwargs``, which sets top-level SDK call arguments. This one **merges into** the body the call site builds (the Orq router retry policy, thread and memory ids) rather than replacing it: your keys win per key, and the call site keeps the keys you did not set. Replacing the whole body is what silently dropped retry hints, which is why ``extra_body`` is rejected inside ``extra_kwargs``.",
          "title": "Extra Body",
          "type": "object"
        },
        "reasoning_effort": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Reasoning effort. Rendered per endpoint by ``request_params``: flat ``reasoning_effort=`` on chat completions, ``reasoning={'effort': ...}`` on the Responses API. Not validated here: accepted values differ per model, so the provider is the only authority \u2014 an unsupported value comes back as a provider 400, which the `common.llm_call` executors turn into a drop-and-retry-once.",
          "title": "Reasoning Effort"
        },
        "client": {
          "default": null,
          "title": "Client"
        },
        "retry_count": {
          "default": 1,
          "description": "Retries after the initial call, for callers that own retry via with_retry \u2014 currently the judge. Same semantics as LLMConfig.retry_count: 0 disables retry. The owning caller disarms the client's own retry budget for the duration (see run_judge) so the two cannot multiply.",
          "minimum": 0,
          "title": "Retry Count",
          "type": "integer"
        }
      },
      "title": "LLMCallConfig",
      "type": "object"
    },
    "SimulationRecommendationConfig": {
      "additionalProperties": false,
      "description": "Tunable limits for simulation recommendation generation.\n\nThresholds are on the judge's 0-1 scales: a conversation-average beyond one of them marks the\nresult as remediable. Defaults preserve prior behaviour; pass an instance to\n``generate_recommendations``/``find_triggers`` to tune. ``RedTeamRecommendationConfig`` is the\nred-teaming twin \u2014 both inherit the shared caps from ``RecommendationConfigBase``.",
      "properties": {
        "max_suggestions": {
          "default": 3,
          "minimum": 1,
          "title": "Max Suggestions",
          "type": "integer"
        },
        "max_tokens": {
          "default": 800,
          "minimum": 1,
          "title": "Max Tokens",
          "type": "integer"
        },
        "factual_accuracy_below": {
          "default": 0.5,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Factual Accuracy Below",
          "type": "number"
        },
        "hallucination_risk_above": {
          "default": 0.5,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Hallucination Risk Above",
          "type": "number"
        },
        "tone_appropriateness_below": {
          "default": 0.5,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Tone Appropriateness Below",
          "type": "number"
        },
        "max_results": {
          "default": 10,
          "minimum": 1,
          "title": "Max Results",
          "type": "integer"
        },
        "max_transcript_chars": {
          "default": 3000,
          "minimum": 100,
          "title": "Max Transcript Chars",
          "type": "integer"
        },
        "max_message_chars": {
          "default": 400,
          "minimum": 50,
          "title": "Max Message Chars",
          "type": "integer"
        },
        "max_verdict_chars": {
          "default": 300,
          "minimum": 50,
          "title": "Max Verdict Chars",
          "type": "integer"
        }
      },
      "title": "SimulationRecommendationConfig",
      "type": "object"
    },
    "SimulationScoringConfig": {
      "additionalProperties": false,
      "description": "Tunables for the two built-in scorers that encode a *policy*, not a fact.\n\n``goal_achieved`` and ``criteria_met`` read the judge's verdicts and have nothing to\ntune. The other two make judgement calls this class exposes, mirroring\n``SimulationRecommendationConfig``: bounded fields, ``extra='forbid'``, and defaults\nthat carry over the previously hardcoded cliffs verbatim. The one deliberate\ndifference is the tail past the last cliff, which now decays from that cliff's score\ninstead of restarting from ``1.0`` \u2014 the old curve scored 7 turns higher than 6, so a\nrun past the last cliff scores lower than it used to. See ``CHANGELOG.md``. Pass an\ninstance as ``simulate(scoring=...)`` /\n``generate_and_simulate(scoring=...)``, or to ``get_evaluator`` /\n``get_all_evaluators`` when driving the scorers directly.\n\n**What `turn_efficiency` measures.** It is a *cost* proxy, not a quality one: given\nthat the goal was reached, how many conversational turns did it take? The assumption\nis that a user who got what they came for in two turns had a better experience \u2014 and\ncost less to serve \u2014 than one who needed twelve, because the extra turns are usually\nthe agent asking for something it could have inferred, re-asking, or wandering. A run\nthat did **not** reach the goal scores ``0.0`` outright: efficiency at failing is not\na virtue worth crediting.\n\n**Where that assumption breaks.** A task that legitimately needs many turns \u2014 a long\nintake form, a multi-step troubleshooting tree, a negotiation \u2014 is penalised by this\nmetric for doing its job properly. If your scenarios look like that, either move the\ncliffs out (``turn_efficiency_cliffs=((6, 1.0), (10, 0.9), (16, 0.7))``) so the curve\nmatches a realistic conversation length, or leave ``turn_efficiency`` out of\n``evaluator_names`` and ignore the score. It is not in\n``DEFAULT_EVALUATOR_NAMES`` precisely because it is not universally meaningful.\n\nWorked example \u2014 a 4-turn conversation that reached its goal and met 1 of 2 criteria,\nscored with the defaults:\n\n```python\nfrom evaluatorq.simulation.evaluators import SimulationScoringConfig, conversation_quality_scorer\n\n# goal_achieved   = 1.0    (the judge set goal_achieved)\n# criteria_met    = 0.5    (1 of 2 criteria met)\n# turn_efficiency = 0.9    (4 turns: past the <=2 cliff, inside the <=4 one)\n#\n# conversation_quality = 1.0 * 0.4 + 0.5 * 0.3 + 0.9 * 0.3\n#                      = 0.4 + 0.15 + 0.27 = 0.82\nconversation_quality_scorer(result)  # 0.82\n\n# Same conversation, scored as if only the goal mattered:\ngoal_only = SimulationScoringConfig(\n    goal_achieved_weight=1.0, criteria_met_weight=0.0, turn_efficiency_weight=0.0\n)\nconversation_quality_scorer(result, goal_only)  # 1.0\n```",
      "properties": {
        "turn_efficiency_cliffs": {
          "default": [
            [
              2,
              1.0
            ],
            [
              4,
              0.9
            ],
            [
              6,
              0.7
            ]
          ],
          "items": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "integer"
              },
              {
                "type": "number"
              }
            ],
            "type": "array"
          },
          "title": "Turn Efficiency Cliffs",
          "type": "array"
        },
        "turn_efficiency_decay_per_turn": {
          "default": 0.1,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Turn Efficiency Decay Per Turn",
          "type": "number"
        },
        "turn_efficiency_floor": {
          "default": 0.3,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Turn Efficiency Floor",
          "type": "number"
        },
        "goal_achieved_weight": {
          "default": 0.4,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Goal Achieved Weight",
          "type": "number"
        },
        "criteria_met_weight": {
          "default": 0.3,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Criteria Met Weight",
          "type": "number"
        },
        "turn_efficiency_weight": {
          "default": 0.3,
          "maximum": 1.0,
          "minimum": 0.0,
          "title": "Turn Efficiency Weight",
          "type": "number"
        }
      },
      "title": "SimulationScoringConfig",
      "type": "object"
    }
  },
